package com.example.starter.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import java.time.Clock;
import java.time.ZoneId;

/**
 * 时钟配置：业务时间统一使用 Asia/Shanghai（UTC+8），测试可替换为可控时钟。
 */
@Configuration
public class ClockConfig {

    public static final ZoneId BUSINESS_ZONE = ZoneId.of("Asia/Shanghai");

    @Bean
    public Clock businessClock() {
        return Clock.system(BUSINESS_ZONE);
    }
}

package com.example.starter.domain;

/**
 * 追保通知状态：OPEN 未结清；RESOLVED 已补足结清；LIQUIDATED 逾期已强平。
 */
public enum MarginCallStatus {
    OPEN,
    RESOLVED,
    LIQUIDATED
}

package com.example.starter.domain;

/**
 * 强平指令状态：PENDING 待发（可撤销）；DONE 已执行（终态）；CANCELLED 已撤销（终态）。
 */
public enum LiquidationStatus {
    PENDING,
    DONE,
    CANCELLED
}

package com.example.starter.domain;

/**
 * 强平触发原因：DIRECT_BELOW_110 比例低于110%直接强平；OVERDUE 追保逾期未补足。
 */
public enum LiquidationReason {
    DIRECT_BELOW_110,
    OVERDUE
}

