                            + " AND status = 'OPEN' AND outstanding = 7250", accountId) == 1);
                }
                // 两种结果下入账均恰好入账一次
                assertEquals(1, queryLong("SELECT COUNT(*) FROM deposit WHERE request_id = ?",
                        "RACE-D-" + round));
            } finally {
                pool.shutdownNow();
                assertTrue(pool.awaitTermination(10, TimeUnit.SECONDS));
